import{_ as n,o as s,c as t,a4 as e}from"./chunks/framework.9tZL7ZIQ.js";const h=JSON.parse('{"title":"重大收购 · 从纺织厂到万亿帝国","description":"","frontmatter":{},"headers":[],"relativePath":"06_visualization/acquisitions-timeline.md","filePath":"06_visualization/acquisitions-timeline.md"}'),i={name:"06_visualization/acquisitions-timeline.md"};function l(p,a,o,r,d,c){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="重大收购-·-从纺织厂到万亿帝国" tabindex="-1">重大收购 · 从纺织厂到万亿帝国 <a class="header-anchor" href="#重大收购-·-从纺织厂到万亿帝国" aria-label="Permalink to &quot;重大收购 · 从纺织厂到万亿帝国&quot;">​</a></h1><blockquote><p>巴菲特60年间的收购历程，从纺织厂到保险、铁路、能源、科技——每次收购都遵循&quot;以合理价格买入优秀企业&quot;的原则。</p></blockquote><h2 id="核心收购时间线" tabindex="-1">核心收购时间线 <a class="header-anchor" href="#核心收购时间线" aria-label="Permalink to &quot;核心收购时间线&quot;">​</a></h2><div class="language-timeline vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">timeline</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    title 伯克希尔重大收购历程</span></span>
<span class="line"><span>    1967 : 收购 National Indemnity（国民赔偿保险）— 860万美元 — 保险帝国起点</span></span>
<span class="line"><span>    1972 : 收购 See&#39;s Candies（喜诗糖果）— 2500万美元 — 消费品牌收购典范</span></span>
<span class="line"><span>    1977 : 收购 Buffalo Evening News（水牛城新闻）— 3250万美元</span></span>
<span class="line"><span>    1983 : 收购 Nebraska Furniture Mart（内布拉斯加家具城）— 6000万美元 — B夫人传奇</span></span>
<span class="line"><span>    1985 : 收购 Scott Fetzer — 3.15亿美元 — 芒格推动</span></span>
<span class="line"><span>    1986 : 收购 Fechheimer Bros — 4600万美元</span></span>
<span class="line"><span>    1996 : 全资收购 GEICO — 23亿美元 — 20年梦想成真</span></span>
<span class="line"><span>    1998 : 收购 General Re（通用再保险）— 220亿美元</span></span>
<span class="line"><span>    1999 : 收购 Jordan&#39;s Furniture — —</span></span>
<span class="line"><span>    2000 : 收购 Benjamin Moore（本杰明·摩尔涂料）— 10亿美元</span></span>
<span class="line"><span>    2000 : 收购 Justin Brands — 6亿美元</span></span>
<span class="line"><span>    2002 : 收购 Fruit of the Loom — 8.35亿美元（破产拍卖）</span></span>
<span class="line"><span>    2006 : 收购 PacifiCorp — 51亿美元 — 能源业务起点</span></span>
<span class="line"><span>    2008 : 收购 Burlington Northern（首次入股）— 铁路帝国</span></span>
<span class="line"><span>    2009 : 投资 BYD（比亚迪）— 2.3亿美元</span></span>
<span class="line"><span>    2010 : 全资收购 BNSF铁路 — 440亿美元 — 伯克希尔最大收购</span></span>
<span class="line"><span>    2013 : 收购 H.J. Heinz（亨氏）— 与3G资本合资</span></span>
<span class="line"><span>    2015 : 收购 Precision Castparts — 372亿美元 — 航空零部件</span></span>
<span class="line"><span>    2020 : 收购 Dominion Energy天然气资产 — 97亿美元</span></span>
<span class="line"><span>    2022 : 收购 Alleghany保险 — 116亿美元</span></span></code></pre></div><h2 id="收购分类统计" tabindex="-1">收购分类统计 <a class="header-anchor" href="#收购分类统计" aria-label="Permalink to &quot;收购分类统计&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>代表公司</th><th>数量</th><th>总投入估算</th></tr></thead><tbody><tr><td>保险</td><td>GEICO、国民赔偿、通用再保险、Alleghany</td><td>10+</td><td>~$400亿</td></tr><tr><td>铁路与能源</td><td>BNSF、PacifiCorp、BHE</td><td>5+</td><td>~$650亿</td></tr><tr><td>制造与服务</td><td>Precision Castparts、Marmon、Lubrizol</td><td>20+</td><td>~$500亿</td></tr><tr><td>消费品牌</td><td>喜诗糖果、可口可乐（持股）、DQ</td><td>5+</td><td>~$400亿（含持股）</td></tr><tr><td>零售</td><td>内布拉斯加家具城、Jordan&#39;s</td><td>5+</td><td>~$50亿</td></tr><tr><td>金融</td><td>美国运通（持股）、穆迪（持股）</td><td>持股</td><td>—</td></tr></tbody></table><h2 id="巴菲特的收购哲学" tabindex="-1">巴菲特的收购哲学 <a class="header-anchor" href="#巴菲特的收购哲学" aria-label="Permalink to &quot;巴菲特的收购哲学&quot;">​</a></h2><blockquote><p><strong>&quot;以公平价格买一家出色的企业，远比以惊人的价格买一家平平的企业好。&quot;</strong> —— 沃伦·巴菲特</p></blockquote><p>巴菲特60年的收购历史，始终围绕一个核心原则：** quality over price（质量优先）**。他从不追逐&quot;便宜货&quot;，而是寻找那些具有持久竞争优势（护城河）、优秀管理层和稳定现金流的优质企业。</p><p>几个关键洞察：</p><ul><li><strong>保险优先</strong>：1967年收购国民赔偿保险，奠定了伯克希尔帝国的资金底盘。保险浮存金成为持续收购的&quot;弹药库&quot;。</li><li><strong>喜诗糖果范式</strong>：2500万美元收购喜诗糖果，几十年来为伯克希尔创造了超过20亿美元的利润，成为&quot;合理价格买优质企业&quot;的经典案例。</li><li><strong>大象级收购</strong>：BNSF铁路（440亿）和 Precision Castparts（372亿）是伯克希尔的两次超大收购，代表了从轻资产到重资产帝国的跨越。</li><li><strong>3G资本合作</strong>：亨氏等交易引入私募基金伙伴，在资本配置上形成互补。</li></ul><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><ul><li><a href="/02_value_investment/buffett-letters/1983.html">巴菲特1983年致股东信——内布拉斯加家具城与B夫人传奇</a></li><li><a href="/03_case_studies/geico.html">GEICO：20年的等待</a></li><li><a href="/04_business_analysis/insurance-moat.html">伯克希尔保险帝国的构建</a></li><li><a href="/03_case_studies/bnsf-acquisition.html">BNSF收购：伯克希尔史上最大交易</a></li></ul>`,13)])])}const m=n(i,[["render",l]]);export{h as __pageData,m as default};
